static NSInteger checks=0;
static void Check(BOOL condition,NSString *message){checks++;if(!condition){NSLog(@"FAIL: %@",message);exit(1);}}
static void Finish(GDEngine *e){for(int i=0;i<40&&e.phase==GDPhaseResolving;i++)[e finishResolution];}
static NSString *BoardHash(GDEngine *e){uint64_t hash=1469598103934665603ULL;for(GDCell *c in e.cells){NSString *str=[NSString stringWithFormat:@"%ld:%ld:%ld;",(long)c.row,(long)c.column,(long)c.color];for(NSUInteger j=0;j<str.length;j++){hash^=[str characterAtIndex:j];hash*=1099511628211ULL;}}return [NSString stringWithFormat:@"%016llx",hash];}
static NSString *TopologyHash(GDEngine *e){NSMutableArray *keys=[NSMutableArray new];for(GDCell *c in e.cells)[keys addObject:c.key];return [keys componentsJoinedByString:@","];}
static void Supported(GDEngine *e){NSMutableArray *queue=[NSMutableArray new];NSMutableSet *seen=[NSMutableSet new];for(GDCell *c in e.cells)if(c.row==0){[queue addObject:c];[seen addObject:c.key];}for(NSUInteger i=0;i<queue.count;i++)for(GDCell *c in [e neighborsOfCell:queue[i]])if(![seen containsObject:c.key]){[seen addObject:c.key];[queue addObject:c];}Check(seen.count==e.cells.count,@"authored wave has no unsupported pre-existing cells");}
static NSDictionary *BestAim(GDEngine *engine){
