    for(NSInteger launcher=0;launcher<3;launcher++){[engine selectLauncher:launcher];CGPoint origin=[engine launcherPoint:launcher];for(NSInteger degrees=-73;degrees<=73;degrees+=3){CGFloat angle=degrees*M_PI/180;CGPoint target=CGPointMake(origin.x+sin(angle)*700,origin.y-cos(angle)*700);GDShot *shot=[engine previewToward:target];if(!shot.valid)continue;NSString *key=[NSString stringWithFormat:@"%ld:%ld:%@",(long)shot.landingRow,(long)shot.landingColumn,shot.blast?shot.hitCell.key:@""];if(shot.expectedMatches.count){NSMutableArray *keys=[NSMutableArray new];for(GDCell *c in shot.expectedMatches)if(![c.key isEqual:[NSString stringWithFormat:@"%ld:%ld",(long)shot.landingRow,(long)shot.landingColumn]])[keys addObject:c.key];key=[[keys sortedArrayUsingSelector:@selector(compare:)] componentsJoinedByString:@","];}if([landings containsObject:key])continue;[landings addObject:key];[options addObject:@{@"launcher":@(launcher),@"x":@(target.x),@"y":@(target.y),@"matches":@(shot.expectedMatches.count),@"row":@(shot.landingRow)}];}}
