    [options sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){NSInteger x=[a[@"matches"] integerValue],y=[b[@"matches"] integerValue];if(x!=y)return x>y?NSOrderedAscending:NSOrderedDescending;x=[a[@"connections"] integerValue];y=[b[@"connections"] integerValue];return x==y?[a[@"row"] compare:b[@"row"]]:x>y?NSOrderedAscending:NSOrderedDescending;}];
    NSDictionary *best=nil;double value=-DBL_MAX;for(NSInteger i=0;i<MIN(10,(NSInteger)options.count);i++){NSDictionary *o=options[i];GDEngine *copy=[[GDEngine alloc]initWithSnapshot:engine.snapshot];Check(copy!=nil,@"in-progress campaign snapshot restores");[copy resume];if(engine.blastArmed)[copy activateSkill:GDColorRed];[copy selectLauncher:[o[@"launcher"] integerValue]];GDShot *shot=[copy previewToward:CGPointMake([o[@"x"] doubleValue],[o[@"y"] doubleValue])];if(![copy beginShot:shot])continue;GDEvent *event=[copy resolveShot];double v=event.removed.count+event.fallen.count*1.8;if(event.placed&&!event.removed.count&&!event.fallen.count)for(GDCell *c in [copy neighborsOfCell:event.placed])v+=c.color==event.placed.color?.6:.05;if(copy.objective==GDObjectiveFall)v+=event.fallen.count*2;if(copy.objective==GDObjectiveCollect)for(GDCell *c in [event.removed arrayByAddingObjectsFromArray:event.fallen])if(c.color==copy.objectiveColor)v+=2;v+=copy.won?1000:0;v-=copy.phase==GDPhaseGameOver?1000:0;v-=[o[@"row"] integerValue]*.03;if(v>value){value=v;best=o;}}
