}
static NSTimeInterval FlightDuration(GDShot *shot){CGFloat length=0;for(NSUInteger i=1;i<shot.points.count;i++){CGPoint a,b;[shot.points[i-1] getValue:&a];[shot.points[i] getValue:&b];length+=hypot(b.x-a.x,b.y-a.y);}return length/1250.;}
// Match the production scene's clocks: flight follows actual path length, all
// resolving events take .38 s, and due pressure remains locked until presented.
static void AdvanceClock(GDEngine *e,NSTimeInterval delta,NSTimeInterval *resolution){
    while(delta>1e-8&&!e.won&&e.phase!=GDPhaseGameOver){
        BOOL resolving=e.phase==GDPhaseResolving;if(resolving&&*resolution<=1e-8)*resolution=.38;
        NSTimeInterval step=resolving?MIN(delta,*resolution):delta;
        if(e.phase==GDPhaseReady){NSTimeInterval untilPressure=e.pressureRemaining+e.freezeRemaining;step=MIN(step,MAX(1e-8,untilPressure));if(e.objective==GDObjectiveSurvive&&e.mode==GDGameModeLevel)step=MIN(step,MAX(1e-8,e.objectiveTarget-e.elapsed));}
        GDEvent *event=[e advanceTime:step];delta-=step;if(resolving)*resolution-=step;
        if(event&&e.phase==GDPhaseResolving)*resolution=.38;
        if(resolving&&*resolution<=1e-8&&e.phase==GDPhaseResolving){GDEvent *next=[e finishResolution];*resolution=next&&e.phase==GDPhaseResolving?.38:0;}
    }
}
static NSDictionary *Replay(GDLevel *level){
    GDEngine *e=[[GDEngine alloc]initWithLevelID:level.levelID seed:level.seed];Supported(e);NSString *hash=BoardHash(e),*topology=TopologyHash(e);NSMutableArray *actions=[NSMutableArray new],*waveClears=[NSMutableArray new];NSInteger shots=0,bounces=0,skills=0;NSTimeInterval resolution=0;NSMutableSet *launchers=[NSMutableSet new];
