        if(e.freezeRemaining==0&&e.pressureRemaining<5&&[e activateSkill:GDColorBlue]){skills++;[actions addObject:@{@"blue":@YES,@"elapsed":@(e.elapsed)}];}
        NSDictionary *aim=BestAim(e);if(!e.holdUsed&&[aim[@"value"] doubleValue]<3){GDEngine *held=[[GDEngine alloc]initWithSnapshot:e.snapshot];[held resume];if([held hold]){NSDictionary *alternative=BestAim(held);if(alternative&&(!aim||[alternative[@"value"] doubleValue]>[aim[@"value"] doubleValue]+.01)){[e hold];[actions addObject:@{@"hold":@YES}];aim=BestAim(e);}}}
        if([aim[@"value"] doubleValue]<3){GDEvent *yellow=[e activateYellow];if(yellow){skills++;[actions addObject:@{@"yellow":@YES,@"elapsed":@(e.elapsed),@"resolution":@.38}];resolution=.38;AdvanceClock(e,2,&resolution);continue;}if([e activateSkill:GDColorWhite]){skills++;[actions addObject:@{@"wild":@YES}];aim=BestAim(e);}else if(!e.blastArmed&&[e activateSkill:GDColorRed]){skills++;[actions addObject:@{@"red":@YES}];aim=BestAim(e);}}
        if(!aim&&e.blastArmed){[e cancelBlast];aim=BestAim(e);}if(!aim){AdvanceClock(e,2,&resolution);continue;}
        NSInteger launcher=[aim[@"launcher"] integerValue];[e selectLauncher:launcher];GDShot *shot=[e previewToward:CGPointMake([aim[@"x"] doubleValue],[aim[@"y"] doubleValue])];Check([e beginShot:shot],@"forward replay accepts its authoritative shot");NSTimeInterval flight=FlightDuration(shot);shots++;bounces+=shot.bounced;[launchers addObject:@(launcher)];[actions addObject:@{@"launcher":@(launcher),@"x":aim[@"x"],@"y":aim[@"y"],@"elapsed":@(e.elapsed),@"current":@(e.currentColor),@"next":@(e.nextColor),@"held":@(e.heldColor),@"blast":@(shot.blast),@"flight":@(flight),@"resolution":@.38,@"planning":@(MAX(0,2-flight-.38))}];[e advanceTime:flight];GDEvent *event=[e resolveShot];if(event.newWave||e.cells.count==0)[waveClears addObject:@{@"authoredWave":@(event.newWave?e.wave-1:e.wave),@"fallen":e.diagnostics[@"stats"][@"fallenRemoved"]?:@0,@"elapsed":@(e.elapsed),@"shots":@(shots)}];if(event.newWave)Supported(e);resolution=.38;AdvanceClock(e,MAX(.38,2-flight),&resolution);
    }}
