    GDEngine *survive=[[GDEngine alloc]initWithLevelID:4 seed:1];NSMutableDictionary *s=[survive.snapshot mutableCopy];s[@"elapsed"]=@(survive.objectiveTarget-1);s[@"pressure"]=@10;s[@"energy"]=@[@20,@0,@0,@0];survive=[[GDEngine alloc]initWithSnapshot:s];[survive resume];Check([survive activateSkill:GDColorBlue],@"survival freeze activated");NSTimeInterval pressure=survive.pressureRemaining;GDEvent *event=[survive advanceTime:2];Check(event.won&&survive.freezeRemaining==28&&survive.pressureRemaining==pressure,@"freeze stops pressure and never survival time");
    GDEngine *collect=[[GDEngine alloc]initWithLevelID:2 seed:1];NSMutableArray *cells=[NSMutableArray new];for(NSInteger r=0;r<=10;r++)[cells addObject:[GDCell row:r column:0 color:GDColorBlue]];[cells addObject:[GDCell row:0 column:8 color:collect.objectiveColor]];[cells addObject:[GDCell row:0 column:9 color:collect.objectiveColor]];[collect loadFixture:cells phase:0 current:collect.objectiveColor next:collect.objectiveColor];s=[collect.snapshot mutableCopy];s[@"collected"]=@(collect.objectiveTarget-3);collect=[[GDEngine alloc]initWithSnapshot:s];[collect resume];event=MatchingShot(collect);Check(event.gameOver&&!event.won&&collect.objectiveCurrent>=collect.objectiveTarget,@"remaining danger wins precedence over achieved collection");
    survive=[[GDEngine alloc]initWithLevelID:4 seed:1];cells=[NSMutableArray new];for(NSInteger r=0;r<=9;r++)[cells addObject:[GDCell row:r column:0 color:GDColorBlue]];[survive loadFixture:cells phase:0 current:GDColorBlue next:GDColorBlue];s=[survive.snapshot mutableCopy];s[@"elapsed"]=@(survive.objectiveTarget-1);s[@"pressure"]=@1;survive=[[GDEngine alloc]initWithSnapshot:s];[survive resume];event=[survive advanceTime:1];Check(event.gameOver&&!event.won,@"due push at survival deadline still checks danger first");
