    s=[endless.snapshot mutableCopy];s[@"score"]=NSNull.null;Check(![[GDEngine alloc]initWithSnapshot:s],@"wrong numeric snapshot types rejected without exception");s=[endless.snapshot mutableCopy];s[@"stats"]=@{@"normalShots":NSNull.null};Check(![[GDEngine alloc]initWithSnapshot:s],@"malformed stats boundary rejected");s=[endless.snapshot mutableCopy];s[@"mode"]=@99;Check(![[GDEngine alloc]initWithSnapshot:s],@"unknown snapshot mode rejected");s=[endless.snapshot mutableCopy];s[@"won"]=@YES;Check(![[GDEngine alloc]initWithSnapshot:s],@"endless cannot restore campaign win");
    s=[endless.snapshot mutableCopy];s[@"operations"]=@[NSNull.null];Check(![[GDEngine alloc]initWithSnapshot:s],@"diagnostics cannot restore non-property-list operations");s[@"format"]=@1;Check(![[GDEngine alloc]initWithSnapshot:s],@"legacy non-property-list operations rejected");s[@"operations"]=@[];Check([[GDEngine alloc]initWithSnapshot:s]!=nil,@"legacy property-list operations remain compatible");
    for(NSInteger expected=1;expected<=3;expected++){survive=[[GDEngine alloc]initWithLevelID:4 seed:1];s=[survive.snapshot mutableCopy];s[@"elapsed"]=@(survive.objectiveTarget-1);s[@"pressure"]=@10;s[@"stats"]=@{@"normalShots":@(expected==1?100:0)};s[@"score"]=@(expected==3?[GDLevelCatalog levelForID:4].parScore:0);survive=[[GDEngine alloc]initWithSnapshot:s];[survive resume];event=[survive advanceTime:1];Check(event.won&&survive.stars==expected,@"survival stars require independent shots and score efficiency");}
