static void Stores(void){NSString *suite=NSUUID.UUID.UUIDString;NSUserDefaults *defaults=[[NSUserDefaults alloc]initWithSuiteName:suite];GDRunRecords *records=[[GDRunRecords alloc]initWithDefaults:defaults];Check(records.records.count==0,@"empty leaderboard");Check([records recordRunID:@"a" score:100 elapsed:30 seed:1 wave:2],@"save record");Check(![records recordRunID:@"a" score:900 elapsed:30 seed:1 wave:2],@"same run only once");[records recordRunID:@"b" score:200 elapsed:10 seed:2 wave:1];[records recordRunID:@"c" score:200 elapsed:20 seed:3 wave:1];Check([records rankForRunID:@"b"]==1&&[records rankForRunID:@"c"]==2&&[records rankForRunID:@"a"]==3,@"sorted score with stable ties");records=[[GDRunRecords alloc]initWithDefaults:defaults];Check(records.records.count==3,@"recreate records store");for(NSInteger i=0;i<55;i++)[records recordRunID:[NSString stringWithFormat:@"extra%ld",(long)i] score:300+i elapsed:i seed:i+1 wave:1];Check(records.records.count==50,@"leaderboard bounded");Check(![records recordRunID:@"a" score:999 elapsed:2 seed:1 wave:1],@"evicted run is still deduplicated");Check(![records recordRunID:@"invalid" score:1 elapsed:NAN seed:1 wave:1],@"nonfinite boundary rejected");GDProgressStore *progress=[[GDProgressStore alloc]initWithDefaults:defaults];Check(progress.unlockedLevel==1&&progress.totalStars==0,@"initial unlock");[progress recordWinForLevel:1 stars:3 score:800];[progress recordWinForLevel:1 stars:1 score:300];Check(progress.unlockedLevel==2&&[progress bestStarsForLevel:1]==3&&[progress bestScoreForLevel:1]==800,@"replay never downgrades");progress=[[GDProgressStore alloc]initWithDefaults:defaults];Check(progress.totalStars==3,@"progress survives recreation");[defaults setObject:@{@"format":@1,@"unlocked":@-1,@"levels":@"invalid"} forKey:@"GDCampaignProgress"];Check(progress.unlockedLevel==1&&[progress bestStarsForLevel:1]==0,@"malformed progress boundary cannot unlock or crash");[defaults setObject:@{@"format":@"invalid"} forKey:@"GDEndl