int main(int argc,const char *argv[]){@autoreleasepool{
    // TestDefaults.m isolates every standard defaults store before main runs.
    Stores();Boundaries();for(GDLevel *level in GDLevelCatalog.levels)if(level.objective==GDObjectiveSurvive){GDEngine *idle=[[GDEngine alloc]initWithLevelID:level.levelID seed:level.seed];for(NSInteger t=0;t<=level.target&&idle.phase!=GDPhaseGameOver&&!idle.won;t++){[idle advanceTime:1];Finish(idle);}Check(idle.phase==GDPhaseGameOver&&idle.elapsed<level.target,@"survival requires player input before target");NSLog(@"IDLE L%02ld loses %.1f before target %ld",(long)level.levelID,idle.elapsed,(long)level.target);}
    NSArray *levels=GDLevelCatalog.levels;Check(levels.count==30,@"30 levels");NSMutableArray *results=[NSMutableArray new];BOOL all=YES;NSMutableSet *hashes=[NSMutableSet new],*topologies=[NSMutableSet new];for(GDLevel *level in levels){if(argc>1&&level.levelID!=atoi(argv[1]))continue;NSDictionary *r=Replay(level);[results addObject:r];[[NSJSONSerialization dataWithJSONObject:r options:NSJSONWritingPrettyPrinted error:nil] writeToFile:[NSString stringWithFormat:@"build/core/replay-level-%02ld.json",(long)level.levelID] atomically:YES];[hashes addObject:r[@"layoutHash"]];[topologies addObject:r[@"topology"]];NSLog(@"REPLAY L%02ld seed=%lu hash=%@ won=%@ objective=%ld %ld/%ld shots=%@ skills=%@ bounces=%@ t=%.1f stars=%@",(long)level.levelID,(unsigned long)level.seed,r[@"layoutHash"],r[@"won"],(long)level.objective,[r[@"progress"] integerValue],(long)level.target,r[@"shots"],r[@"skills"],r[@"bounces"],[r[@"elapsed"] doubleValue],r[@"stars"]);all&=[r[@"won"] boolValue];}
    NSData *json=[NSJSONSerialization dataWithJSONObject:results options:NSJSONWritingPrettyPrinted error:nil];[json writeToFile:@"build/core/campaign-replays.json" atomically:YES];if(argc==1){Check(hashes.count==30,@"each full opening layout is distinct");Check(topologies.count>=24,@"opening geometry differs beyond recolouring");for(NSDictionary *r in results)Check([r[@"shots"] integerValue]>3,@"no level degenerates to three shots or less");}NSLog(@"REPLAY COMPLETE count=%lu unique=%lu topology=%lu assertions=%ld allWon=%d",(unsigned long)results.count,(unsigned long)hashes.count,(unsigned long)topologies.count,(long)checks,all);return all?0:1;
